// ELEMENTS:
// 1. Fundo navy liso
// 2. Nome em serifa branca (name / anim.text) + "CONSULTOR IMOBILIÁRIO" (role), primeiro
// 3. Retrato do agente (src) grande, retangular, a abrir de baixo para cima
// 4. "VISITAS POR MARCAÇÃO" (label), telefone (phone) em bloco coral, email (email)
// 5. Logótipo (logo) ou marca (brand) + licença AMI (ami), no fim
// 6. Faixa da agência (banner) opcional, a toda a largura no rodapé
// 7. Grão de filme + vinheta
import React, { useId } from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, Easing } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#001F44";
const CYAN = "#DE212B";
const CORAL = "#DE212B";
const INK = "#001F44";
const WHITE = "#FFFFFF";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const Grain: React.FC<{ f: number }> = ({ f }) => {
  const id = useId().replace(/:/g, "");
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.22) 100%)" }} />
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0, opacity: 0.1, mixBlendMode: "overlay" }}>
        <filter id={id}>
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={f % 12} />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${id})`} />
      </svg>
    </AbsoluteFill>
  );
};

const AgenteRevelacao: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const H = box.height;
  const land = format === "landscape";
  const u = land ? H / 1080 : format === "half" ? (H / 960) * 0.85 : W / 1080;
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const s = (k: string): string => (p[k] == null ? "" : String(p[k]).trim());
  const src = s("src");
  const name = s("name") || String(anim.text ?? "").trim();
  const phone = s("phone");
  const email = s("email");
  const amiRaw = s("ami");
  const ami = amiRaw ? (amiRaw.toLowerCase().includes("ami") ? amiRaw : `AMI ${amiRaw}`) : "";
  const brand = s("brand") || "RE/MAX";
  const label = s("label") || "Visitas por marcação";
  const role = s("role") || "Consultor imobiliário";
  const banner = s("banner");
  const logo = s("logo");
  // ponytail: room kept for a wide strip (~6:1, the agency banners); other shapes are letterboxed in it.
  const bannerH = banner ? Math.min(W / 5.9, H * 0.18) : 0;

  const show = (delay: number, len = 0.7): number =>
    interpolate(f, [Math.round(delay * fps), Math.round((delay + len) * fps)], [0, 1], { ...clamp, easing: EASE });
  const rise = (delay: number): React.CSSProperties => {
    const t = show(delay);
    return { opacity: t, transform: `translateY(${(1 - t) * 20 * u}px)` };
  };
  const open = show(0.3, 0.9);
  // Portrait: as big as the space left under the name and above the contacts allows (700u wide at most).
  const photoH = land ? (H - bannerH) * 0.62 * 1.27 : Math.max(120 * u, Math.min(700 * 1.27 * u, H - 870 * u - (banner ? bannerH + 48 * u : 0)));
  const photoW = land ? (H - bannerH) * 0.62 : photoH / 1.27;
  const nameSize = Math.min(112 * u, ((land ? W * 0.45 : W) - 144 * u) / Math.max(6, name.length * 0.46));
  const small: React.CSSProperties = { fontFamily: FONTS.body, fontWeight: 600, letterSpacing: "0.22em", textTransform: "uppercase", color: WHITE };

  const heading = (
    <div style={{ display: "flex", flexDirection: "column", alignItems: land ? "flex-start" : "center", gap: 18 * u }}>
      {name ? <div style={{ fontFamily: FONTS.display, fontVariantNumeric: "lining-nums", fontWeight: 300, fontSize: nameSize, lineHeight: 1, color: WHITE, ...rise(0.1) }}>{name}</div> : null}
      <div style={{ ...small, fontSize: 36 * u, letterSpacing: "0.24em", ...rise(0.25) }}>{role}</div>
    </div>
  );
  const photo = (
    <div style={{ width: photoW, height: photoH, flexShrink: 0, overflow: "hidden", clipPath: `inset(${(1 - open) * 100}% 0 0 0)` }}>
      {src ? (
        <Img
          src={src}
          style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: "50% 20%", filter: "saturate(0.9) contrast(1.04)", transform: `scale(${1.06 - 0.06 * open})` }}
        />
      ) : null}
    </div>
  );
  const contacts = (
    <div style={{ display: "flex", flexDirection: "column", alignItems: land ? "flex-start" : "center", gap: 22 * u }}>
      <div style={{ ...small, fontSize: 34 * u, ...rise(0.9) }}>{label}</div>
      {phone ? (
        <div style={{ background: CORAL, color: WHITE, textShadow: "none", borderRadius: 999, padding: `${26 * u}px ${56 * u}px`, fontFamily: FONTS.body, fontWeight: 600, fontSize: 44 * u, letterSpacing: "0.12em", ...rise(1.0) }}>
          {phone}
        </div>
      ) : null}
      {email ? <div style={{ ...small, fontSize: 36 * u, letterSpacing: "0.08em", textTransform: "none", ...rise(1.15) }}>{email}</div> : null}
    </div>
  );
  const licence = (
    <div style={{ display: "flex", flexDirection: "column", alignItems: land ? "flex-start" : "center", gap: 10 * u, ...rise(1.3) }}>
      {logo ? <Img src={logo} style={{ height: 96 * u, width: "auto", objectFit: "contain" }} /> : <div style={{ fontFamily: FONTS.body, fontWeight: 800, fontSize: 44 * u, letterSpacing: "0.04em", color: WHITE }}>{brand}</div>}
      {ami ? <div style={{ ...small, fontSize: 30 * u, letterSpacing: "0.2em" }}>{ami}</div> : null}
    </div>
  );

  // Name first, then the portrait, then the contacts, then the brand and licence.
  return (
    <AbsoluteFill style={{ textShadow: "0 2px 18px rgba(0,0,0,0.45)", backgroundColor: NAVY }}>
      <div
        style={{
          position: "absolute",
          inset: 0,
          bottom: bannerH,
          padding: land ? `${72 * u}px ${96 * u}px` : `${130 * u}px ${96 * u}px ${110 * u}px`,
          boxSizing: "border-box",
          display: "flex",
          flexDirection: land ? "row" : "column",
          alignItems: "center",
          justifyContent: "center",
          gap: (land ? 96 : 48) * u,
          textAlign: land ? "left" : "center",
        }}
      >
        {land ? (
          <>
            {photo}
            <div style={{ display: "flex", flexDirection: "column", gap: 48 * u, flex: 1 }}>
              {heading}
              {contacts}
              {licence}
            </div>
          </>
        ) : (
          <>
            {photo}
            <div style={{ width: show(0.5) * 44 * u, height: 6 * u, background: CORAL }} />
            {heading}
            {contacts}
            {licence}
          </>
        )}
      </div>
      {banner ? (
        <div style={{ position: "absolute", left: 0, right: 0, bottom: 0, height: bannerH, overflow: "hidden", opacity: show(1.45), clipPath: `inset(0 ${(1 - show(1.45, 0.9)) * 100}% 0 0)` }}>
          <Img src={banner} style={{ width: "100%", height: "100%", objectFit: "contain" }} />
        </div>
      ) : null}
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 6 * u, background: "#DE212B" }} />
      <Grain f={f} />
    </AbsoluteFill>
  );
};

export default AgenteRevelacao;

