    <div
      style={{
        position: "relative",
        flexShrink: 0,
        width: side,
        height: side,
        boxSizing: "border-box",
        border: `${Math.max(2, 6 * u)}px solid ${COLORS.teal}`,
        backgroundColor: COLORS.vellum,
        overflow: "hidden",
