              backgroundColor: COLORS.mutedOnLight,
              opacity: 0.45,
            }}
          />
          <div
            style={{
              position: "absolute",
              left: "15%",
              bottom: 0,
              width: "70%",
              height: "34%",
              borderRadius: "50% 50% 0 0",
              backgroundColor: COLORS.mutedOnLight,
              opacity: 0.45,
            }}
          />
        </>
      )}
    </div>
  );

  // Phone / email pills, then the AMI licence on its own row underneath them.
  const buttonsEl =
    contacts.length || ami ? (
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: land ? "flex-start" : "center",
          gap: btnGap,
          maxWidth: textW,
        }}
      >
        {contacts.length ? (
          <div
            style={{
              display: "flex",
              flexDirection: half ? "row" : "column",
              alignItems: land ? "flex-start" : "center",
              justifyContent: "center",
              gap: btnGap,
              maxWidth: textW,
            }}
          >
            {contacts.map((c, i) => pill(c, i, btnMax, btnBase, `c${i}`))}
          </div>
        ) : null}
        {ami ? pill(ami, contacts.length, textW, btnBase * 0.8, "ami") : null}
      </div>
    ) : null;

  return (
    <AbsoluteFill style={{ fontFamily: FONTS.display, alignItems: "center", justifyContent: "center" }}>
      <div style={{ display: "flex", flexDirection: land ? "row" : "column", alignItems: "center", gap }}>
        {!land && nameEl}
        {imageEl}
        {land ? (
          <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-start", gap: 36 * u, width: textW }}>
            {nameEl}
            {buttonsEl}
          </div>
        ) : (
          buttonsEl
        )}
      </div>
    </AbsoluteFill>
  );
};

